import {} from './table-ui.mjs';
import {} from './live-court.mjs';
import {} from './navigation.mjs';
import { predictMatchCoaches } from './coach-predictions.mjs';
import { normalizeCompetition } from './match-data.mjs';
import { coaches, coachFor, coachStatistics } from './coaches.mjs';
import { makeMotmPoster } from './motm-poster.mjs';
import { isGoalkeeper } from './goalkeepers.mjs';
import { buildForecast } from './forecast.mjs';
import { refreshPolicy, nextPolicyCheck, courtLabel } from './schedule.mjs';
import { summarizeMatch } from './match-stats.mjs';
import { championshipSelections, selectionsForPlayer } from './selections.mjs';
import { matchPreview, nextRoundMatches, VENUE } from './match-preview.mjs';
import { makeMatchFlyer } from './match-flyer.mjs';
import { updateVisitors } from './visitors.mjs';
import { startVersionChecks } from './version-check.mjs';
import { matchAwards } from './awards.mjs';
import { calculateScores, SCORE_RULES, scoreDataStatus, playerAppearances } from './player-score.mjs';
import { matchRecap } from './match-recap.mjs';
const BASE='https://copafacil-web.firebaseio.com/events/-ciddy';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const parseStats=s=>Object.fromEntries(String(s??'').split('#').filter(x=>x.includes('=')).map(x=>{const[k,v]=x.split('=');return[k,Number(v)||0]}));
const name=v=>String(v??'A definir').trim().toLocaleLowerCase('pt-BR').replace(/(^|\s)\S/g,c=>c.toLocaleUpperCase('pt-BR'));
const initials=n=>name(n).split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('');
const safeURL=u=>{try{const x=new URL(u);return x.protocol==='https:'?esc(x.href):''}catch{return''}};
let db,teams=[],players=[],matches=[],phases=[],rounds=[],view='overview',busy=false,playerPage=1;
let forecast=null,ranking=[];
const matchSheets=new Map(),sheetRequests=new Map();
let activeMatchId=null,activeFlyerId=null,flyerURL=null;
let selectionId=championshipSelections.at(-1)?.id;
let refreshTimer=null,lastRefreshAttempt=0;
let filters={team:'',phase:'',round:'',status:'',query:'',sort:'goals'};
const isFinished=m=>Number(m.st)===3||Boolean(m.finished);
const hasScore=m=>Number.isFinite(m.dt?.qt_g1)&&Number.isFinite(m.dt?.qt_g2);
const team=id=>db?.teams?.[id];
function crest(id){const t=team(id);return t?.url?`<img class="crest" src="${safeURL(t.url)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:`<span class="badge-fallback">${esc(initials(t?.name||'?'))}</span>`}
function goalkeeperBadge(p){return isGoalkeeper(p.id,p.team)?'<small class="goalkeeper-badge">Goleiro · Camisa 1</small>':''}
function avatar(p){return p.url?`<img class="avatar" src="${safeURL(p.url)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:`<span class="avatar avatar-fallback">${esc(initials(p.name))}</span>`}
function fmtDate(m,opts={day:'2-digit',month:'short'}){return m.d_i?new Intl.DateTimeFormat('pt-BR',{...opts,timeZone:'America/Sao_Paulo'}).format(new Date(m.d_i)):'Data a definir'}
function fmtTime(m){return m.d_i?new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'}).format(new Date(m.d_i)):'Horário a definir'}
const FIRST_PHASE='1780479913323';
const PHASE_NAMES={
  '1780479913323':'Primeira Fase',
  '1780479913324':'Repescagem',
  '1780480689653':'Quartas de Finais',
  '1780480702080':'Semi Finais',
  '1780480718514':'Grande FINAL'
};
function phaseLabel(id){return PHASE_NAMES[id]||'Fase não identificada'}
function roundLabel(m){const group=rounds.filter(r=>r.fs===m.fs);return m.m_set?`Rodada ${group.findIndex(r=>r.id===m.m_set)+1}`:'Rodada a definir'}
function prepare(data){data=normalizeCompetition(data);for(const [id,entry] of Object.entries(data.matchDetails||{})){if(!matchSheets.has(id)||entry.fetchedAt>matchSheets.get(id).fetchedAt)matchSheets.set(id,entry)}db=data;forecast=buildForecast(data);recalculateScores();teams=Object.entries(db.teams||{}).map(([id,t])=>({id,...t}));matches=Object.entries(db.matchs||{}).map(([id,m])=>({id,...m})).sort((a,b)=>(a.d_i||Infinity)-(b.d_i||Infinity));phases=[...new Set(matches.map(m=>m.fs).filter(Boolean))];rounds=[...new Map(matches.filter(m=>m.m_set).map(m=>[m.m_set,{id:m.m_set,fs:m.fs}])).values()]}
function standings(phase=FIRST_PHASE){if(phase!==FIRST_PHASE)return [];return teams.map(t=>{const source=t.dt?.[phase];const stats=source?.dt?parseStats(source.dt):null;const ms=matches.filter(m=>m.fs===phase&&isFinished(m)&&hasScore(m)&&(m.team1===t.id||m.team2===t.id));const c={j:0,v:0,e:0,d:0,gp:0,gc:0,pts:0};for(const m of ms){const gf=m.team1===t.id?m.dt.qt_g1:m.dt.qt_g2;const ga=m.team1===t.id?m.dt.qt_g2:m.dt.qt_g1;c.j++;c.gp+=gf;c.gc+=ga;if(gf>ga)c.v++;else if(gf===ga)c.e++;else c.d++}c.pts=c.v*3+c.e;return{...t,j:stats?.[1]??c.j,v:stats?.[2]??c.v,e:stats?.[3]??c.e,d:stats?.[4]??c.d,gp:stats?.[5]??c.gp,gc:stats?.[6]??c.gc,sg:stats?.[7]??(c.gp-c.gc),pts:stats?.[0]??c.pts,percent:stats?.[8]??(c.j?Math.round(c.pts/(c.j*3)*100):0),rank:source?.col,form:ms.slice(-5).map(m=>{const a=m.team1===t.id?m.dt.qt_g1:m.dt.qt_g2,b=m.team1===t.id?m.dt.qt_g2:m.dt.qt_g1;return a>b?'V':a<b?'D':'E'})}}).sort((a,b)=>(a.rank??999)-(b.rank??999)||b.pts-a.pts||b.sg-a.sg||b.gp-a.gp||a.name.localeCompare(b.name))}
function teamButton(id){return `<button class="team-button" data-team="${esc(id)}">${crest(id)}<span>${esc(name(team(id)?.name))}</span></button>`}
function qualificationClass(phase,position){if(phase!==phases[0])return '';return position>=1&&position<=4?'qualification-quarterfinal':position<=8&&position>=5?'qualification-advantage':position>=9&&position<=12?'qualification-playoff':''}
function qualificationLegend(phase){return phase===phases[0]?`<div class="qualification-legend"><p><b>Vagas ao final da Primeira Fase</b></p><span><i class="quarterfinal-swatch" aria-hidden="true"></i><b>1º ao 4º:</b> direto para as quartas de final.</span><span><i class="advantage-swatch" aria-hidden="true"></i><b>5º ao 8º:</b> repescagem com vantagem do empate.</span><span><i class="playoff-swatch" aria-hidden="true"></i><b>9º ao 12º:</b> repescagem sem vantagem do empate.</span></div>`:''}
function tableHTML(full=false,phase=FIRST_PHASE){if(phase!==FIRST_PHASE)return '';const rows=standings(phase),projection=full&&phase===phases[0];return `<div class="table-wrap"><table class="${full?'full-table':''}"><thead><tr><th scope="col">#</th><th class="team-cell" scope="col">Equipe</th><th scope="col">PTS</th><th scope="col" title="Jogos">J</th><th scope="col" title="Vitórias">V</th><th scope="col" title="Empates">E</th><th scope="col" title="Derrotas">D</th>${full?'<th scope="col" title="Gols pró">GP</th><th scope="col" title="Gols contra">GC</th>':''}<th scope="col" title="Saldo de gols">SG</th>${full?'<th scope="col">Aprov.</th>':''}${projection?'<th scope="col" title="Chance de terminar entre os quatro primeiros">Chance G4</th><th scope="col" title="Chance de terminar entre os oito primeiros">Chance G8</th>':''}<th scope="col">Últimos</th></tr></thead><tbody>${rows.map((t,i)=>`<tr class="${qualificationClass(phase,t.rank!=null?t.rank+1:i+1)}"><td class="position">${t.rank!=null?t.rank+1:i+1}</td><td class="team-cell">${teamButton(t.id)}</td><td class="points">${t.pts}</td><td>${t.j}</td><td>${t.v}</td><td class="muted">${t.e}</td><td class="muted">${t.d}</td>${full?`<td>${t.gp}</td><td>${t.gc}</td>`:''}<td>${t.sg>0?'+':''}${t.sg}</td>${full?`<td>${t.percent}%</td>`:''}${projection?`<td class="qualification-probability">${qualificationChance(t.id,'top4')}</td><td class="qualification-probability">${qualificationChance(t.id,'top8')}</td>`:''}<td><div class="form">${t.form.length?t.form.map(f=>`<span title="${f==='V'?'Vitória':f==='D'?'Derrota':'Empate'}" class="${f==='V'?'win':f==='D'?'loss':''}">${f}</span>`).join(''):'<span>–</span>'}</div></td></tr>`).join('')}</tbody></table></div>${qualificationLegend(phase)}`}
function statusLabel(m){return isFinished(m)?hasScore(m)?'Encerrado':'Encerrado · placar pendente':m.st?'Status não identificado':'Agendado'}
function scoreHTML(m){return hasScore(m)?`${m.dt.qt_g1}<small>:</small>${m.dt.qt_g2}`:`<small>${isFinished(m)?'—':'×'}</small>`}
function percent(p){return (p*100).toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})+'%'}
function odd(value){return value==null?'—':value.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})}
function predictionFor(m){return !isFinished(m)&&m.d_i>Date.now()?forecast?.predictions.find(p=>p.matchId===m.id):null}
function fixtureOdds(m){const p=predictionFor(m);if(!p)return '';if(p.status!=='ready')return `<div class="odds-unavailable">${p.status==='awaiting_teams'?'Odds disponíveis quando as equipes forem definidas.':'Aguardando resultados anteriores para simular.'}</div>`;const labels=[name(team(m.team1)?.name),'Empate',name(team(m.team2)?.name)];return `<div class="odds-caption">Odds estimadas <span>1 · X · 2</span></div><div class="odds-strip">${p.odds.map((v,i)=>`<span class="odd-cell" title="${esc(labels[i])}: ${percent(p.probabilities[i])}"><span>${['1','X','2'][i]}</span><b>${odd(v)}</b><small>${percent(p.probabilities[i])}</small></span>`).join('')}</div>`}
function probabilityBar(p){return `<div class="probability-bar" aria-label="Probabilidades: primeira equipe ${percent(p.probabilities[0])}, empate ${percent(p.probabilities[1])}, segunda equipe ${percent(p.probabilities[2])}">${p.probabilities.map((v,i)=>`<span class="probability-${i}" style="width:${v*100}%"></span>`).join('')}</div>`}
function forecastEvidence(p){if(p.status!=='ready')return '';return `<div class="forecast-evidence">${probabilityBar(p)}<div class="prediction-facts"><span>Placar mais frequente<b>${p.topScores[0].score.replace('-',' × ')} <small>${percent(p.topScores[0].probability)}</small></b></span><span>Gols esperados<b>${p.expectedGoals.map(x=>x.toLocaleString('pt-BR',{maximumFractionDigits:2})).join(' × ')}</b></span></div><p class="subtle">Base das equipes: ${p.teamGames[0]} e ${p.teamGames[1]} jogos.${p.teamGames.includes(0)?' Equipe sem jogos utiliza a média da liga.':''}${p.limitedHistory?' Amostra pequena; estimativa exploratória.':''}</p></div>`}
function matchForecastDetail(m){const p=predictionFor(m);if(!p)return '';return `<h3 class="detail-section">Simulação da rodada</h3>${fixtureOdds(m)}${forecastEvidence(p)}<p class="subtle">20.000 cenários · Odds decimais calculadas como 1 ÷ probabilidade, sem margem comercial. ${p.status==='ready'?'O placar mais frequente é apenas um dos resultados possíveis.':''}</p><a href="#odds" class="text-link">Ver metodologia e toda a rodada →</a>`}
function oddsView(){const f=forecast;const first=f.predictions.length?matches.find(m=>m.id===f.predictions[0].matchId):null;const ready=f.predictions.filter(p=>p.status==='ready');const date=t=>new Date(t).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'});return sectionTitle('Odds & simulações',`${first?roundLabel(first)+' · ':''}Projeções de vitória, empate e derrota.`,`${f.predictions.length} confrontos`)+`<section class="forecast-summary"><div><span class="eyebrow">APÓS CADA RODADA</span><h3>${f.completedRounds.length} rodadas encerradas</h3><p>${f.cutoff?`Último encerramento registrado: ${date(f.cutoff)} · Brasília`:'Aguardando uma rodada completa'}</p><p>Recalculado quando a consulta confirma todos os placares finais da rodada.</p></div><div><b>${ready.length?'20.000':'—'}</b><span>cenários por partida</span></div><div><b>${f.historyCount}</b><span>resultados anteriores</span></div></section><div class="odds-legend"><span><b>1</b> Vitória da primeira equipe</span><span><b>X</b> Empate</span><span><b>2</b> Vitória da segunda equipe</span></div><div class="cards-grid odds-cards">${f.predictions.map(p=>{const m=matches.find(m=>m.id===p.matchId);return `<section class="panel"><div class="forecast-match-date">${fmtDate(m,{weekday:'short',day:'numeric',month:'short'})}</div>${fixture(m)}${forecastEvidence(p)}</section>`}).join('')}</div>${!f.predictions.length?'<div class="panel empty">Nenhuma próxima rodada com data futura cadastrada. As simulações aparecerão quando o calendário for atualizado.</div>':''}<p class="subtle">Projeções estatísticas, sem vínculo com casas de apostas. Uma odd de 2,00 representa 50% de probabilidade estimada. O modelo não foi calibrado para garantir precisão nesta competição.</p><details class="forecast-method"><summary>Como são calculadas as odds?</summary><div><p>Simulamos 20.000 placares por confronto com uma distribuição de Poisson para os gols de cada equipe. As probabilidades de vitória, empate e derrota são as frequências observadas; a odd decimal é 1 dividido por essa probabilidade, sem margem.</p><p>Usamos somente resultados de rodadas com todos os jogos encerrados e placares finais publicados. Uma rodada parcialmente concluída só entra na base após o último resultado. Cada equipe considera seus últimos 8 jogos disponíveis, combinando ataque próprio e defesa adversária. A média de gols da liga tem peso de 4 jogos adicionais para reduzir distorções em amostras pequenas. Sem jogos anteriores da liga, não há previsão.</p><p>Uma equipe sem histórico parte da média da competição. Não presumimos vantagem de mando e não usamos escalações, lesões ou suspensões. Os gols das duas equipes são modelados de forma independente. Muitas simulações reduzem a oscilação do cálculo, mas não compensam a falta de resultados anteriores.</p><p>A página confere o encerramento das rodadas ao abrir e nas atualizações de dados: em dias de jogos, a cada 10 minutos. Não há mais espera pela segunda-feira. A verificação de apoio ocorre diariamente às 4h de Brasília, incluindo o domingo após jogos de sábado. Correções dos resultados de rodadas encerradas também ajustam as projeções. Partidas já iniciadas ou encerradas deixam de exibir odds pré-jogo. As probabilidades podem somar 99,9% ou 100,1% por arredondamento.</p><p>Referência matemática: <a href="https://docs.scipy.org/doc/scipy/reference/generated/scipy.stats.poisson.html" target="_blank" rel="noreferrer">distribuição de Poisson ↗</a>.</p></div></details>`}
function coachAvatar(c){return `<img class="coach-avatar" src="${c.photo?safeURL(c.photo):'images/coach-placeholder.svg'}" alt="${c.photo?'':'Foto ainda não disponível'}" loading="lazy">`}
function coachButton(c){return `<button class="coach-person" data-coach="${esc(c.id)}">${coachAvatar(c)}<span>${esc(c.name)}<small>Técnico/Professor</small></span></button>`}
function predictedCoachesHTML(m){
  const prediction=predictMatchCoaches(m,db);if(!prediction)return '';
  const note=prediction.shared.length?`${prediction.shared.map(c=>c.name).join(' / ')} já treinou os dois times. A definição depende da escolha do técnico.`:'Previsão pelo histórico das equipes e alternância de quadras. Sujeita à confirmação.';
  return `<span class="fixture-coaches coach-prediction">${prediction.sides.map(s=>`<span>${s.confirmed?'Técnico confirmado':'Previsão de técnico'}: <b>${s.coach?esc(s.coach.name):'A definir'}</b></span>`).join('')}<small>${esc(note)}</small></span>`;
}
function fixtureCoachCaption(m){if(!isFinished(m))return predictedCoachesHTML(m);const staff=[m.team1,m.team2].map(id=>coachFor(m.id,id));return staff.some(Boolean)?`<span class="fixture-coaches">${staff.map(c=>`<span>Técnico: <b>${c?esc(c.name):'Não informado'}</b></span>`).join('')}</span>`:''}
function matchCoachesHTML(m){if(!isFinished(m))return predictedCoachesHTML(m);return `<section class="match-coaches"><h3>Técnicos/Professores nesta partida</h3><div class="coach-pair">${[m.team1,m.team2].map(id=>{const c=coachFor(m.id,id);return `<div><p>${esc(name(team(id)?.name))}</p>${c?coachButton(c):'<span class="subtle">Ainda não informado</span>'}</div>`}).join('')}</div></section>`}
function coachesView(){const rows=coachStatistics(db).sort((a,b)=>(b.played?b.points/b.played:-1)-(a.played?a.points/a.played:-1)||b.gd-a.gd||b.gf-a.gf||a.name.localeCompare(b.name,'pt-BR'));return sectionTitle('Técnicos/Professores','Ordenados por maior aproveitamento, depois saldo de gols e gols feitos.',`${rows.length} técnicos/professores`)+`<section class="panel"><div class="table-wrap"><table class="full-table"><thead><tr><th>Técnico/Professor</th><th>J</th><th>V</th><th>E</th><th>D</th><th>GP</th><th>GC</th><th>SG</th><th>Aprov.</th></tr></thead><tbody>${rows.map(c=>`<tr><td>${coachButton(c)}</td><td>${c.played}</td><td>${c.wins}</td><td>${c.draws}</td><td>${c.losses}</td><td>${c.gf}</td><td>${c.ga}</td><td>${signed(c.gd)}</td><td>${c.played?c.percent+'%':'—'}</td></tr>`).join('')}</tbody></table></div></section><p class="subtle">J: jogos · V: vitórias · E: empates · D: derrotas · GP: gols pró · GC: gols sofridos · SG: saldo de gols. Cada jogo conta pela equipe comandada. Apenas partidas encerradas com placar e técnico informado entram nas estatísticas. Toque no nome para ver o histórico.</p>`}
function openCoach(id){const c=coachStatistics(db).find(c=>c.id===id);if(!c)return;showDetail(`<div class="profile-heading">${coachAvatar(c)}<div><h2 id="detail-title">${esc(c.name)}</h2><p>Técnico/Professor · ${new Set(c.games.map(g=>g.teamId)).size} equipes comandadas</p></div></div>${detailMetrics([[c.played,'Jogos'],[c.wins,'Vitórias'],[c.draws,'Empates'],[c.losses,'Derrotas']])}<div class="detail-info"><div><span>Gols pró / sofridos</span>${c.gf} / ${c.ga}</div><div><span>Saldo de gols</span>${signed(c.gd)}</div><div><span>Aproveitamento</span>${c.played?c.percent+'%':'—'}</div><div><span>Jogos sem sofrer gols</span>${c.cleanSheets}</div></div><h3 class="detail-section">Equipes treinadas</h3><div class="coach-team-grid">${[...new Set(c.games.map(g=>g.teamId))].map(id=>teamButton(id)).join('')||'<p class="subtle">Nenhuma equipe registrada.</p>'}</div><h3 class="detail-section">Histórico de partidas</h3><div class="coach-history">${c.games.map(g=>{const m=matches.find(m=>m.id===g.matchId);return `<button data-match="${esc(g.matchId)}"><span class="badge coach-result-${g.result}">${{V:'Vitória',E:'Empate',D:'Derrota'}[g.result]}</span><span><b>${esc(name(team(g.teamId)?.name))}</b> × ${esc(name(team(g.opponentId)?.name))}<small>${roundLabel(m)} · ${fmtDate(m)} · Comandou ${esc(name(team(g.teamId)?.name))}${g.substituteFor?' · Substituiu '+esc(coaches.find(c=>c.id===g.substituteFor)?.name||g.substituteFor):''}</small></span><strong>${g.gf} x ${g.ga}</strong></button>`}).join('')||'<p class="subtle">Nenhuma partida encerrada com placar registrado.</p>'}</div><p class="subtle">Os técnicos são informados pela organização em cada partida. Trocas nas próximas rodadas preservam este histórico.</p>`)}
async function openMotmPoster(id){
  const m=matches.find(m=>m.id===id),a=awardFor(id);if(!m||!a)return;
  showDetail(`<h2 id="detail-title">Man of the Match · ${esc(name(db.player?.[a.playerId]?.name||a.name))}</h2><p class="subtle">Arte para Instagram · PNG · 1080 × 1350 · Foto original e logo VIW.</p><div id="motm-poster-result" role="status"><p class="subtle">Preparando sua imagem…</p></div>`);activeFlyerId='motm:'+id;
  try{
    const canvas=await makeMotmPoster(m,db,a);
    const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Não foi possível preparar o download.')),'image/png'));
    if(activeFlyerId!=='motm:'+id||!$('#detail').open)return;
    flyerURL=URL.createObjectURL(blob);
    $('#motm-poster-result').innerHTML=`<img class="motm-poster-image" src="${flyerURL}" width="1080" height="1350" alt="Man of the Match: ${esc(a.name)} — ${esc(name(team(m.team1)?.name))} × ${esc(name(team(m.team2)?.name))}"><div class="flyer-actions"><a class="button selection-download" href="${flyerURL}" download="viw-man-of-the-match-${esc(id)}.png">Baixar imagem para Instagram ↓</a><a class="text-link" href="${flyerURL}" target="_blank" rel="noopener">Abrir imagem ↗</a></div>`;
  }catch(e){if(activeFlyerId==='motm:'+id)$('#motm-poster-result').innerHTML=`<p class="sheet-warning">${esc(e.message||'Não foi possível gerar a imagem.')}</p><button class="button" data-motm-poster="${esc(id)}">Tentar novamente</button>`;}
}

function awardFor(id){return matchAwards.find(a=>a.matchId===id)}
function awardCard(m){const award=awardFor(m.id);if(!award)return '';const p=db.player?.[award.playerId];return `<section class="motm-banner"><div class="motm-photo">${p?avatar(p):''}</div><div class="motm-copy"><span class="eyebrow">MELHOR EM CAMPO</span><h3>${esc(name(p?.name||award.name))}</h3>${p?goalkeeperBadge({id:award.playerId,...p}):''}<p>${esc(name(team(award.teamId)?.name))} · Escolha da organização</p>${p?`<button class="text-link" data-player="${esc(award.playerId)}">Ver jogador</button>`:''}<button class="text-link motm-art-button" data-motm-poster="${esc(m.id)}">Imagem para Instagram ↓</button></div><span class="award-mark" aria-hidden="true">★</span></section>`}
function recapHTML(m){
  const recap=matchRecap(m,db,matchSheets.get(m.id)?.data,awardFor(m.id));if(!recap)return '';
  return `<section class="match-preview match-newspaper match-recap"><div class="newspaper-kicker">DEPOIS DO APITO FINAL</div><h3>${esc(recap.headline)}</h3><p class="recap-intro">${esc(recap.intro)}</p><div class="newspaper-columns">${recap.columns.map(c=>`<section class="newspaper-column"><h4>${crest(c.teamId)}${esc(c.name)}</h4>${c.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</section>`).join('')}</div>${recap.coverageNote?`<p class="subtle">${esc(recap.coverageNote)}</p>`:''}${awardCard(m)}${!awardFor(m.id)?`<p class="subtle">${esc(recap.awardText)}</p>`:''}</section>`;
}
function motmView(){const awards=matchAwards.filter(a=>db.matchs?.[a.matchId]);return sectionTitle('Melhor em campo','Os protagonistas de cada partida, escolhidos pela organização.',`${awards.length} prêmios`)+`<div class="cards-grid motm-grid">${awards.map(a=>{const m=matches.find(m=>m.id===a.matchId);return `<article class="panel motm-card"><div class="motm-card-meta">${roundLabel(m)} · ${fmtDate(m)}</div>${awardCard(m)}${fixture(m)}<button class="text-link motm-read" data-match="${esc(m.id)}">Ler o jornal da partida →</button></article>`}).join('')}</div>`}
function playerAwardsHTML(id){const awards=matchAwards.filter(a=>a.playerId===id&&db.matchs?.[a.matchId]);return awards.length?`<section class="player-selection-history"><h3>★ Melhor em campo</h3><p>${awards.length} ${awards.length===1?'prêmio':'prêmios'}</p>${awards.map(a=>{const m=matches.find(m=>m.id===a.matchId);return `<button class="text-link" data-match="${esc(m.id)}">${roundLabel(m)} · ${esc(name(team(m.team1)?.name))} × ${esc(name(team(m.team2)?.name))}</button>`}).join('')}</section>`:''}
function signed(n){return n>0?'+'+n:String(n)}
function recalculateScores(){if(!db)return;db.matchDetails=Object.fromEntries(matchSheets);ranking=calculateScores(db,matchAwards,championshipSelections);const counts=playerAppearances(db);players=Object.entries(db.player||{}).map(([id,p])=>{const appearances=counts.get(id)||{total:0,byPhase:{}};return {id,...p,appearances,stats:{...parseStats(p.dt),2:appearances.total}}})}
function scoreStatusHTML(){const {pending,stale}=scoreDataStatus(db);return `${pending?`<p class="sheet-warning" role="status">Pontuação parcial: ${pending} ${pending===1?'partida aguarda':'partidas aguardam'} a relação de uma ou mais equipes. Resultados e defesa só pontuam os jogadores com relação confirmada.</p>`:''}${stale?'<p class="sheet-warning" role="status">Algumas súmulas não puderam ser atualizadas. A pontuação usa a última relação disponível.</p>':''}`}
function playerScoreHTML(id){const row=ranking.find(p=>p.id===id);if(!row)return '';return `<section class="player-score"><div class="player-score-heading"><h3>MVP</h3><b>${row.total} <small>pontos</small></b></div><div class="score-ledger">${row.components.map(c=>`<div><span>${esc(c.label)} <small>${c.count} × ${signed(c.points)}</small></span><b class="${c.earned<0?'negative-points':''}">${signed(c.earned)}</b></div>`).join('')}</div>${scoreStatusHTML()}${!row.hasStats?'<p class="subtle">Pontuação parcial: estatísticas individuais ainda não informadas.</p>':''}<p class="subtle">Resultados e pontos defensivos contam apenas nos jogos em que o atleta foi relacionado como presente, pela equipe registrada na súmula. Reservas são ausentes e não recebem esses pontos. Sem sofrer gols: +5 para o goleiro ou +2 para jogadores de linha. Cada gol sofrido: −1 para cada relacionado, incluindo o goleiro.</p><a href="#ballon" class="text-link">Ver a classificação completa →</a></section>`}
function scoreView(){
  const all=ranking.filter(p=>p.active),rows=all.filter(p=>(!filters.team||p.team===filters.team)&&normalize(p.name).includes(normalize(filters.query)));
  const pages=Math.max(1,Math.ceil(rows.length/20));playerPage=Math.min(playerPage,pages);
  const sum=(p,keys)=>p.components.filter(c=>keys.includes(c.key)).reduce((n,c)=>n+c.earned,0);
  return sectionTitle('MVP','A corrida pelo melhor jogador do campeonato.',`${all.length} jogadores pontuando`)+scoreStatusHTML()+`<div class="filters"><input type="search" data-filter="query" aria-label="Buscar jogador no ranking" placeholder="Buscar jogador…" value="${esc(filters.query)}"><select data-filter="team" aria-label="Filtrar ranking por equipe">${teamOptions(filters.team)}</select></div><section class="panel score-panel"><div class="table-wrap"><table class="full-table"><thead><tr><th>#</th><th class="team-cell">Jogador</th><th class="team-cell">Equipe</th><th>Pontos</th><th>Gols</th><th>Cartões</th><th>Resultados</th><th>Defesa</th><th>Prêmios</th></tr></thead><tbody>${rows.map(p=>`<tr><td class="position">${p.rank}</td><td><button class="player-name" data-player="${esc(p.id)}">${avatar(p)}<span>${esc(name(p.name))}${goalkeeperBadge(p)}${!p.hasStats?'<small>Pontuação parcial</small>':''}</span></button></td><td class="team-cell">${teamButton(p.team)}</td><td class="score-total ${p.total<0?'negative-points':''}">${p.total}</td><td>${signed(sum(p,['goals']))}</td><td class="negative-points">${signed(sum(p,['yellow','red']))}</td><td>${signed(sum(p,['wins','draws','losses']))}</td><td>${signed(sum(p,['goalkeeperCleanSheets','outfieldCleanSheets','goalsAgainst']))}</td><td>${signed(sum(p,['motm','selections']))}</td></tr>`).join('')}</tbody></table></div>${!rows.length?'<p class="empty">Nenhum jogador encontrado.</p>':''}<div class="pagination"><span>${rows.length} jogadores · Página ${playerPage} de ${pages}</span><div><button class="button" data-page="prev" ${playerPage===1?'disabled':''}>← Anterior</button><button class="button" data-page="next" ${playerPage===pages?'disabled':''}>Próxima →</button></div></div></section><p class="subtle">As colunas mostram pontos. Toque no jogador para conferir o cálculo. Empates compartilham a posição; a ordem alfabética é apenas visual. Quem ainda não tem eventos, prêmios ou partidas como relacionado aguarda para entrar no ranking.</p><details class="forecast-method" open><summary>Regras da pontuação</summary><div class="score-rules">${SCORE_RULES.map(r=>`<div><span>${esc(r.label)}</span><b class="${r.points<0?'negative-points':''}">${signed(r.points)}</b></div>`).join('')}</div><p>Vitórias, empates e derrotas valem apenas para os jogadores relacionados como presentes na súmula de cada partida. Neste campeonato, quem aparece como reserva faltou ao jogo. Reservas e jogadores não relacionados não ganham nem perdem pontos pelo resultado ou pela defesa da equipe. Gols e cartões usam os totais publicados pelo Copa Fácil. Os prêmios são informados pela organização. Em cada partida encerrada sem sofrer gols, o goleiro recebe +5 e os jogadores de linha +2, sem acumular os dois bônus. Cada gol sofrido desconta 1 ponto de cada relacionado, incluindo o goleiro. Esses pontos defensivos usam o placar final e a equipe registrada na súmula daquele jogo. Sem a relação publicada, esses pontos ficam pendentes.</p></details>`;
}
function previewFor(m){return matchPreview(m,{...db,matchDetails:Object.fromEntries(matchSheets)},championshipSelections)}
function isNextRound(m){return nextRoundMatches(db).some(x=>x.id===m.id)}
function previewHTML(m){const preview=previewFor(m);if(!preview)return '';return `<section class="match-preview match-newspaper"><div class="newspaper-kicker">JORNAL DA RODADA</div><h3>${esc(preview.headline)}</h3><div class="newspaper-columns">${preview.columns.map(column=>`<section class="newspaper-column"><h4>${crest(column.teamId)}${esc(column.name)}</h4><p>${esc(column.story)}</p>${column.highlights.length?`<div class="newspaper-highlights">${column.highlights.map(p=>`<p>${esc(p.text)}</p>`).join('')}</div>`:''}</section>`).join('')}</div></section>`}

function flyerButton(m){return isNextRound(m)&&team(m.team1)&&team(m.team2)?`<button class="button flyer-button" data-flyer="${esc(m.id)}">Ver panfleto e baixar ↓</button>`:''}
async function openFlyer(id){
  const m=matches.find(m=>m.id===id);if(!m||!isNextRound(m))return;
  showDetail(`<h2 id="detail-title">Panfleto da partida</h2><p class="subtle">${esc(name(team(m.team1)?.name))} × ${esc(name(team(m.team2)?.name))}</p><div id="flyer-result" role="status"><p class="subtle">Preparando a imagem com os escudos e o horário atualizado…</p></div>`);activeFlyerId=id;
  try{
    const canvas=await makeMatchFlyer(m,db,`${phaseLabel(m.fs)} · ${roundLabel(m)}`);
    const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Não foi possível gerar a imagem.')),'image/png'));
    if(activeFlyerId!==id||!$('#detail').open)return;
    if(!isNextRound(m))throw Error('A próxima rodada foi atualizada. Abra novamente a partida.');
    flyerURL=URL.createObjectURL(blob);
    $('#flyer-result').innerHTML=`<img class="match-flyer-image" src="${flyerURL}" width="1080" height="1350" alt="Panfleto: ${esc(name(team(m.team1)?.name))} × ${esc(name(team(m.team2)?.name))}, ${fmtDate(m)}, ${fmtTime(m)}, Pro Beach"><div class="flyer-actions"><a class="button selection-download" href="${flyerURL}" download="la-liga-viw-${esc(m.id)}.png">Baixar panfleto PNG ↓</a><a class="text-link" href="${flyerURL}" target="_blank" rel="noopener">Abrir imagem ↗</a></div>`;
  }catch(e){if(activeFlyerId===id)$('#flyer-result').innerHTML=`<p class="sheet-warning">${esc(e.message||'Não foi possível gerar o panfleto.')}</p><button class="button" data-flyer="${esc(id)}">Tentar novamente</button>`;}
}
function fixtureCrest(m,id,away=false){
  const rank=m.fs===FIRST_PHASE&&!isFinished(m)&&isNextRound(m)?team(id)?.dt?.[FIRST_PHASE]?.col:null;
  const badge=Number.isInteger(rank)&&rank>=0?`<small class="fixture-position" title="Posição atual na Primeira Fase" aria-label="${rank+1}º lugar na classificação atual">${rank+1}º</small>`:'';
  return `<span class="fixture-crest-position">${away?'':badge}${crest(id)}${away?badge:''}</span>`;
}
function fixture(m){return `<button class="fixture" data-match="${esc(m.id)}"><div class="fixture-meta"><span>${fmtTime(m)}${m.title?' · '+esc(courtLabel(m.title)):''}</span><span class="badge ${isFinished(m)?'neutral':''}">${statusLabel(m)}</span></div><div class="fixture-body"><span class="fixture-team">${fixtureCrest(m,m.team1)}<span>${esc(name(team(m.team1)?.name))}</span></span><span class="score">${scoreHTML(m)}</span><span class="fixture-team">${fixtureCrest(m,m.team2,true)}<span>${esc(name(team(m.team2)?.name))}</span></span></div>${fixtureOdds(m)}${fixtureCoachCaption(m)}</button>`}

function scorerRows(limit=4){const ps=[...players].filter(p=>p.stats[0]>0).sort((a,b)=>b.stats[0]-a.stats[0]||a.name.localeCompare(b.name));return ps.slice(0,limit).map((p,i)=>`<button class="scorer-row" data-player="${esc(p.id)}"><span class="scorer-rank">${1+ps.findIndex(x=>x.stats[0]===p.stats[0])}</span>${avatar(p)}<span class="scorer-name">${esc(name(p.name))}<small>${esc(name(team(p.team)?.name))}</small></span><span class="goal-pill">${p.stats[0]}</span></button>`).join('')||'<div class="empty">Nenhum gol registrado.</div>'}
function overview(){const done=matches.filter(isFinished),goals=done.filter(hasScore).reduce((n,m)=>n+m.dt.qt_g1+m.dt.qt_g2,0);const pending=matches.filter(m=>!isFinished(m)&&m.team1&&m.team2);const next=pending.filter(m=>m.d_i>=Date.now());const upcoming=forecast.predictions.map(p=>matches.find(m=>m.id===p.matchId)).filter(Boolean);return `<section class="metric-grid"><div class="metric dark"><span class="metric-label">Partidas disputadas</span><span class="metric-mark">↗</span><div class="metric-number">${done.length}<span style="font-size:23px;color:#8591a6"> / ${matches.length}</span></div><div class="metric-foot">${matches.length-done.length} partidas sem resultado final</div></div><div class="metric"><span class="metric-label">Gols na competição</span><span class="metric-mark">◎</span><div class="metric-number">${goals}</div><div class="metric-foot">${done.length?(goals/done.length).toLocaleString('pt-BR',{maximumFractionDigits:1}):'0'} gols por partida</div></div><div class="metric"><span class="metric-label">Equipes na disputa</span><span class="metric-mark">⚑</span><div class="metric-number">${teams.length}</div><div class="metric-foot">${phases.length} fases com partidas cadastradas</div></div><div class="metric"><span class="metric-label">Jogadores inscritos</span><span class="metric-mark">↗</span><div class="metric-number">${players.length}</div><div class="metric-foot">${players.filter(p=>p.stats[0]>0).length} jogadores já marcaram</div></div></section><div class="overview-grid"><section class="panel"><div class="panel-heading"><div><h2>Classificação</h2><p>${phaseLabel(phases[0])} · Todas as equipes</p></div><a class="text-link" href="#standings">Tabela completa ↗</a></div>${tableHTML()}<div class="panel-note">Posições conforme a fonte. <b>V</b> vitória · <b>E</b> empate · <b>D</b> derrota<br>Toque em uma equipe para explorar o elenco e as partidas.</div></section><div class="side-stack"><section class="panel"><div class="panel-heading"><h2>Próxima rodada · Odds</h2><span class="round-pill">${upcoming.length?roundLabel(upcoming[0]):'Agenda'}</span></div><div class="fixture-group">${upcoming.length?`<div class="fixture-date">${fmtDate(upcoming[0],{weekday:'long',day:'numeric',month:'long'})}</div>${upcoming.map(fixture).join('')}`:'<div class="empty">Nenhuma partida agendada.</div>'}</div><div class="sidebar-bottom"><a href="#matches" class="text-link">Ver todos os jogos →</a><a href="#odds" class="text-link">Entender as odds ↗</a></div></section><section class="panel"><div class="panel-heading"><h2>Artilharia</h2><a href="#players" class="text-link">Ver todos ↗</a></div>${scorerRows()}<div class="panel-note">Gols registrados por jogador. Empates compartilham posição.</div></section></div></div>`}
function options(list,value){return list.map(([id,label])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('')}
function teamOptions(value){return options([['','Todas as equipes'],...teams.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(t=>[t.id,name(t.name)])],value)}
function phaseOptions(value,all=true){return options([...(all?[['','Todas as fases']]:[]),...phases.map(id=>[id,phaseLabel(id)])],value)}
function sectionTitle(title,description,count){return `<div class="section-title"><div><h2>${title}</h2><p>${description}</p></div>${count!==undefined?`<span class="round-pill">${count}</span>`:''}</div>`}
function normalize(s){return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function liveCourtButton(m){const courts=m?(!isFinished(m)?[courtLabel(m.title)==='Quadra 1'?1:courtLabel(m.title)==='Quadra 2'?2:null].filter(Boolean):[]):[1,2];return courts.length?`<div class="live-entry">${courts.map(c=>`<button class="button" data-live-court="${c}">Assistir Quadra ${c} ao vivo</button>`).join(' ')}<small>Duas câmeras lado a lado · sujeito à disponibilidade da transmissão.</small></div>`:''}
function matchView(){const list=matches.filter(m=>(!filters.team||m.team1===filters.team||m.team2===filters.team)&&(!filters.phase||m.fs===filters.phase)&&(!filters.round||m.m_set===filters.round)&&(!filters.status||(filters.status==='finished'?isFinished(m):!isFinished(m))));const groups=Object.groupBy?Object.groupBy(list,m=>fmtDate(m,{year:'numeric',month:'long',day:'numeric',weekday:'long'})):list.reduce((o,m)=>{const k=fmtDate(m,{year:'numeric',month:'long',day:'numeric',weekday:'long'});(o[k]??=[]).push(m);return o},{});return sectionTitle('Agenda & resultados','Horários de Brasília · Toque em uma partida para ver os detalhes.',`${list.length} partidas`)+liveCourtButton()+`<div class="filters"><select aria-label="Filtrar partidas por equipe" data-filter="team">${teamOptions(filters.team)}</select><select aria-label="Filtrar partidas por fase" data-filter="phase">${phaseOptions(filters.phase)}</select><select aria-label="Filtrar partidas por rodada" data-filter="round">${options([['','Todas as rodadas'],...rounds.filter(r=>!filters.phase||r.fs===filters.phase).map(r=>[r.id,`${phaseLabel(r.fs)} · ${roundLabel({m_set:r.id,fs:r.fs})}`])],filters.round)}</select><select aria-label="Filtrar por situação" data-filter="status">${options([['','Todas as situações'],['scheduled','Sem resultado final'],['finished','Encerradas']],filters.status)}</select><button class="button" data-reset>Limpar filtros</button></div>${list.length?Object.entries(groups).map(([date,ms])=>`<section class="match-day"><h3>${esc(date)}</h3><div class="cards-grid">${ms.map(m=>`<div>${fixture(m)}<p class="subtle" style="margin-top:7px">${phaseLabel(m.fs)} · ${roundLabel(m)}</p>${flyerButton(m)}${liveCourtButton(m)}</div>`).join('')}</div></section>`).join(''):'<div class="panel empty">Nenhuma partida encontrada com esses filtros.</div>'}<p class="subtle">Rodadas numeradas pela ordem de suas primeiras partidas. Local dos jogos: Pro Beach · Av. Cézar Magnani, N° 840 - Paulicéia, São Bernardo do Campo - SP, 09694-000. Nomes das fases definidos pela organização. Partidas sem equipes definidas continuam visíveis na agenda.</p>`}
function qualificationChance(id,key){
  const q=forecast?.qualification,row=q?.status==='ready'?q.teams.find(t=>t.id===id):null;
  if(!row)return '—';
  const p=row[key];
  if(p===0)return '0%';if(p===1)return '100%';
  if(p<.001)return '&lt;0,1%';if(p>.999)return '&gt;99,9%';
  return (p*100).toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})+'%';
}
function qualificationSummary(phase){
  if(phase!==phases[0])return '';
  const q=forecast?.qualification;
  if(q?.status!=='ready')return `<div class="panel qualification-summary"><h2>Projeção G4 e G8</h2><p>${q?.status==='insufficient_history'?'Aguardando uma rodada inteira com placares finais para estimar as chances.':'Aguardando calendário e equipes definidos para simular a Primeira Fase.'}</p></div>`;
  return `<section class="panel qualification-summary"><div class="section-title"><div><h2>Quanto falta para G4 e G8?</h2><p>${q.remainingGames?'20.000 simulações até o fim da Primeira Fase':'Primeira Fase encerrada'} · ${q.completedRounds} rodadas completas na base</p></div></div><div class="qualification-targets">${[['top4','G4 · Quartas de final'],['top8','G8 · Vantagem na repescagem']].map(([key,label])=>{const c=q.cutoffs[key];return `<div><span>${label}</span><strong>${c.median} <small>pontos</small></strong><p>${q.remainingGames?`Corte provável · faixa de ${c.low} a ${c.high} pontos em 80% dos cenários`:'Pontuação na posição de corte'}</p></div>`}).join('')}</div><p>A projeção estima a pontuação do 4º e do 8º colocado ao final da fase. Atingir esse número não garante a posição: outras equipes podem empatar em pontos. G8 inclui as equipes do G4.</p>${q.partialRoundResults?'<p class="sheet-warning">Rodada em andamento: as chances ainda usam a última rodada completa. A tabela oficial já pode mostrar resultados mais recentes.</p>':''}<details class="forecast-method"><summary>Como calculamos as chances?</summary><p>Usamos ${q.historyCount} resultados de rodadas completas e simulamos ${q.remainingGames} partidas restantes do calendário cadastrado (${q.scheduledGames} no total). O calendário atual prevê ${Math.min(...q.teams.map(t=>t.totalGames))===Math.max(...q.teams.map(t=>t.totalGames))?q.teams[0].totalGames:'quantidades diferentes de'} jogos por equipe. Mudanças na tabela de jogos alteram a projeção.</p><p>Gols seguem o mesmo modelo das odds: ataque e defesa dos últimos 8 jogos, média da liga com peso de 4 partidas e sem vantagem de mando. Cada vitória vale 3 pontos e cada empate, 1. Ordenamos por pontos, vitórias, saldo de gols e gols marcados. Nos empates restantes, cada equipe tem chances iguais na simulação. ${q.officialFinal?'Com a fase encerrada, usamos as posições oficiais da fonte.':''}</p><p>O corte provável é a mediana; a faixa mostra os percentis 10 e 90 dos pontos na posição de corte. As porcentagens são a frequência de cada equipe no G4 e G8 nas simulações, não uma garantia. A amostra ainda é pequena.</p><p>Odds e classificação projetada usam rodadas completas. Ao consultar novos dados, o site incorpora a rodada assim que todos os jogos estiverem encerrados com placares válidos, independentemente do dia da semana. Resultados isolados de uma rodada aberta não mudam a base.</p></details></section>`;
}
function standingsView(){const exists=teams.some(t=>t.dt?.[FIRST_PHASE]);return sectionTitle('Classificação completa','Primeira Fase · Posições e números registrados no Copa Fácil.')+`${qualificationSummary(FIRST_PHASE)}<section class="panel">${exists?tableHTML(true,FIRST_PHASE):'<div class="empty">A fonte ainda não disponibilizou uma classificação para esta fase.</div>'}<div class="panel-note"><b>PTS</b> pontos · <b>J</b> jogos · <b>V</b> vitórias · <b>E</b> empates · <b>D</b> derrotas · <b>GP</b> gols pró · <b>GC</b> gols contra · <b>SG</b> saldo de gols · <b>Aprov.</b> aproveitamento.<br>A classificação existe apenas na Primeira Fase. Preservamos as posições oficiais da fonte.</div></section>`}
function teamsView(){const list=standings().filter(t=>normalize(t.name).includes(normalize(filters.query)));return sectionTitle('As equipes','Elencos, desempenho e todos os confrontos.',`${teams.length} equipes`)+`<div class="filters"><input type="search" aria-label="Buscar equipe" data-filter="query" placeholder="Buscar equipe…" value="${esc(filters.query)}"></div><div class="cards-grid">${list.map(t=>`<button class="team-card" data-team="${esc(t.id)}"><div class="team-card-top">${crest(t.id)}<div><h3>${esc(name(t.name))}</h3><p>${t.rank!=null?t.rank+1+'º lugar · ':''}${phaseLabel(phases[0])}</p></div></div><div class="team-card-stats"><span><b>${t.pts}</b>Pontos</span><span><b>${t.gp}</b>Gols</span><span><b>${players.filter(p=>p.team===t.id).length}</b>Jogadores</span></div></button>`).join('')}</div>${!list.length?'<div class="empty">Nenhuma equipe encontrada.</div>':''}`}
function statValue(p,code){return code===2?p.appearances.total:p.dt!=null?(p.stats[code]||0):'—'}
function playerTable(ps,rank=false){return `<div class="table-wrap"><table class="full-table"><thead><tr>${rank?'<th scope="col">#</th>':''}<th class="team-cell" scope="col">Jogador</th><th class="team-cell" scope="col">Equipe</th><th scope="col" title="Gols">G</th><th scope="col" title="Jogos">J</th><th scope="col" title="Cartões amarelos">C.AM</th><th scope="col" title="Cartões vermelhos">C.VM</th></tr></thead><tbody>${ps.map((p,i)=>`<tr>${rank?`<td class="position">${(playerPage-1)*20+i+1}</td>`:''}<td><button class="player-name" data-player="${esc(p.id)}">${avatar(p)}<span>${esc(name(p.name))}${goalkeeperBadge(p)}${p.SUSP?'<small>Registro de suspensão</small>':''}</span></button></td><td class="team-cell">${teamButton(p.team)}</td><td class="${filters.sort==='goals'?'stat-highlight':''}">${statValue(p,0)}</td><td>${statValue(p,2)}</td><td class="${filters.sort==='cards'?'stat-highlight':''}">${statValue(p,14)}</td><td class="${filters.sort==='red'?'red-highlight':''}">${statValue(p,16)}</td></tr>`).join('')}</tbody></table></div>`}
function playerResults(){const ps=players.filter(p=>(!filters.team||p.team===filters.team)&&normalize(p.name).includes(normalize(filters.query))&&(!filters.status||(filters.status==='suspension'?Boolean(p.SUSP):filters.status==='scorers'?p.stats[0]>0:filters.status==='red'?p.stats[16]>0:p.stats[14]>0)));const code=filters.sort==='red'?16:filters.sort==='cards'?14:filters.sort==='games'?2:0;ps.sort((a,b)=>filters.sort==='name'?a.name.localeCompare(b.name):Number(b.dt!=null)-Number(a.dt!=null)||(b.stats[code]||0)-(a.stats[code]||0)||a.name.localeCompare(b.name));const pages=Math.max(1,Math.ceil(ps.length/20));playerPage=Math.min(playerPage,pages);return {ps,pages}}
function playersView(){const{ps,pages}=playerResults();const goalTotal=players.reduce((n,p)=>n+(p.stats[0]||0),0),scoreTotal=matches.filter(m=>isFinished(m)&&hasScore(m)).reduce((n,m)=>n+m.dt.qt_g1+m.dt.qt_g2,0);return sectionTitle('Jogadores & estatísticas','Gols, participações e disciplina de cada jogador.',`${ps.length} jogadores`)+`<div class="filters"><input type="search" data-filter="query" aria-label="Buscar jogador" placeholder="Buscar jogador…" value="${esc(filters.query)}"><select data-filter="team" aria-label="Filtrar jogadores por equipe">${teamOptions(filters.team)}</select><select data-filter="sort" aria-label="Ordenar jogadores">${options([['goals','Mais gols'],['games','Mais jogos'],['cards','Mais cartões amarelos'],['red','Mais cartões vermelhos'],['name','Nome A–Z']],filters.sort)}</select><select data-filter="status" aria-label="Filtrar jogadores por estatística">${options([['','Todos os jogadores'],['scorers','Com gols'],['cards','Com cartões amarelos'],['red','Com cartões vermelhos'],['suspension','Com registro de suspensão']],filters.status)}</select></div><section class="panel">${ps.length?playerTable(ps,true):'<div class="empty">Nenhum jogador encontrado com esses filtros.</div>'}<div class="pagination"><span>${ps.length?`${(playerPage-1)*20+1}–${Math.min(playerPage*20,ps.length)} de ${ps.length}`:'0 jogadores'}</span><div><button class="button" data-page="prev" ${playerPage===1?'disabled':''}>← Anterior</button><button class="button" data-page="next" ${playerPage===pages?'disabled':''}>Próxima →</button></div></div></section><p class="subtle"><b>G</b> gols · <b>J</b> partidas encerradas com presença confirmada · <b>C.AM</b> cartões amarelos · <b>C.VM</b> cartões vermelhos. Reservas e não relacionados não contam como presentes. Súmulas ainda indisponíveis não entram na contagem de jogos. “—” indica que a fonte ainda não informou gols ou cartões. Empates são exibidos em ordem alfabética.${goalTotal!==scoreTotal?` Há ${goalTotal} gols atribuídos a jogadores e ${scoreTotal} nos placares; a fonte ainda apresenta essa diferença.`:''}</p>`}
function selectionView(){
  const round=championshipSelections.find(r=>r.id===selectionId)||championshipSelections.at(-1);
  const title=sectionTitle('Seleção do campeonato','Os destaques de cada rodada, com histórico de todas as escolhas.');
  if(!round)return title+'<div class="empty">Aguardando a primeira seleção do campeonato.</div>';
  const totalPlayers=new Set(championshipSelections.flatMap(r=>r.players.map(p=>p.playerId))).size;
  return title+`<div class="selection-toolbar"><label for="selection-round">Consultar rodada</label><select id="selection-round" data-selection-round>${championshipSelections.slice().reverse().map(r=>`<option value="${esc(r.id)}" ${r.id===round.id?'selected':''}>Rodada ${r.roundNumber} · ${r.season}</option>`).join('')}</select><span>${championshipSelections.length} ${championshipSelections.length===1?'rodada registrada':'rodadas registradas'} · ${totalPlayers} jogadores selecionados</span></div>
  <section class="selection-hero"><div><div class="eyebrow">OS DESTAQUES DA RODADA</div><h3>Seleção da ${round.roundNumber}ª rodada<span>.</span></h3><p>${esc(round.source)} · Temporada ${round.season}</p></div><div class="selection-total"><b>${round.players.length}</b><span>jogadores escolhidos</span></div></section>
  ${round.poster?`<section class="selection-art"><a class="selection-art-preview" href="${esc(round.poster)}" target="_blank" rel="noopener" aria-label="Abrir imagem da seleção da ${round.roundNumber}ª rodada"><img src="${esc(round.poster)}" width="1080" height="1350" alt="Seleção da ${round.roundNumber}ª rodada da La Liga Viw: ${esc(round.players.map(p=>p.name).join(', '))}"></a><div class="selection-art-info"><div class="eyebrow">ARTE DA RODADA</div><h3>A seleção em uma imagem.</h3><p>Os sete escolhidos da rodada com suas fotos originais. Salve a arte para guardar ou compartilhar.</p><div class="selection-art-actions"><a class="button selection-download" href="${esc(round.poster)}" download="la-liga-viw-selecao-${round.roundNumber}-rodada.png">Baixar imagem PNG ↓</a><a class="text-link" href="${esc(round.poster)}" target="_blank" rel="noopener">Abrir em tamanho completo ↗</a></div><small>PNG · 1080 × 1350 · Rodada ${round.roundNumber}</small></div></section>`:''}
  <div class="selection-grid">${round.players.map(p=>{const current=db.player?.[p.playerId];const count=selectionsForPlayer(p.playerId).length;return `<article class="selection-card"><span class="selection-star" aria-hidden="true">★</span>${avatar(current||p)}<h3>${esc(p.name)}</h3><div class="selection-team">${crest(p.teamId)}<span>${esc(p.teamName)}</span></div><p class="selection-count">${count} ${count===1?'vez na seleção':'vezes na seleção'}</p>${current?`<button class="button" data-player="${esc(p.playerId)}" aria-label="Ver perfil de ${esc(p.name)}">Ver jogador ↗</button>`:'<p class="subtle">Perfil indisponível na fonte atual.</p>'}</article>`}).join('')}</div>
  <div class="selection-note"><b>Um histórico que conta.</b><p>As escolhas ficam registradas por rodada e por jogador para apoiar as futuras avaliações. As próximas seleções serão adicionadas conforme forem informadas pela organização.</p></div>`;
}
function playerSelectionHistory(id){
  const history=selectionsForPlayer(id);
  if(!history.length)return '';
  return `<section class="player-selection-history"><h3>★ Seleção do campeonato</h3><p><b>${history.length} ${history.length===1?'vez selecionado':'vezes selecionado'}</b></p><div class="selection-history-list">${history.map(r=>{const p=r.players.find(p=>p.playerId===id);return `<span class="round-pill">Rodada ${r.roundNumber} · ${r.season} · ${esc(p.teamName)}</span>`}).join('')}</div></section>`;
}
function render(){if(!db)return;document.querySelectorAll('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const active=document.activeElement;const input=active?.matches('input[data-filter]')?{key:active.dataset.filter,start:active.selectionStart,end:active.selectionEnd}:null;$('#content').innerHTML=({overview,standings:standingsView,matches:matchView,teams:teamsView,players:playersView,odds:oddsView,selection:selectionView,motm:motmView,ballon:scoreView,coaches:coachesView}[view]||overview)();if(input){const el=document.querySelector(`input[data-filter="${input.key}"]`);if(el){el.focus({preventScroll:true});if(el.type!=='search')el.setSelectionRange(input.start,input.end);else try{el.setSelectionRange(input.start,input.end)}catch{}}}}
function detailMetrics(items){return `<div class="detail-metrics">${items.map(([value,label])=>`<div><b>${esc(value)}</b>${esc(label)}</div>`).join('')}</div>`}
function statTags(p){return [['goals','gol','gols'],['yellow','amarelo','amarelos'],['red','vermelho','vermelhos'],['blue','azul','azuis'],['ownGoals','gol contra','gols contra']].filter(([key])=>p[key]>0).map(([key,singular,plural])=>`<span class="event-tag event-${key}">${p[key]} ${p[key]===1?singular:plural}</span>`).join('')}
function matchStatistics(m){
  const entry=matchSheets.get(m.id),loading=sheetRequests.has(m.id);
  const heading=`<div class="match-stat-heading"><h3>Gols e cartões da partida</h3><button class="text-link" data-sheet-refresh="${esc(m.id)}" ${loading?'disabled':''}>${loading?'Atualizando…':'Atualizar súmula ↻'}</button></div>`;
  if(!entry)return heading+`<p class="subtle">${loading?'Buscando os eventos desta partida…':'Carregando a súmula…'}</p>`;
  const summary=summarizeMatch(entry.data,m,db.player);
  const state=entry.error?`<p class="sheet-warning" role="status">${entry.data?'Não foi possível atualizar a súmula. Mostrando a última consulta disponível.':'Não foi possível carregar a súmula. Tente atualizar novamente.'}</p>`:'';
  if(!summary.hasEvents)return heading+state+`<p class="subtle">${entry.error&&!entry.data?'Os detalhes desta partida estão temporariamente indisponíveis.':isFinished(m)?'A fonte ainda não publicou gols ou cartões individuais para esta partida.':'Os gols e cartões aparecerão aqui quando forem registrados nesta partida.'}</p>`;
  const groupHTML=id=>{const ps=summary.players.filter(p=>p.teamId===id);return `<section class="match-team-stats"><h4>${id?crest(id):''}${id?esc(name(team(id)?.name)):'Equipe não identificada'}</h4>${ps.length?ps.map(p=>`<div class="match-event-player">${p.playerId&&db.player[p.playerId]?`<button class="player-name" data-player="${esc(p.playerId)}">${avatar(db.player[p.playerId])}<span>${esc(name(p.name))}</span></button>`:`<span>${esc(name(p.name))}</span>`}<div class="event-tags">${statTags(p)}</div></div>`).join(''):'<p class="subtle">Nenhum gol ou cartão registrado para esta equipe.</p>'}</section>`};
  const mismatch=summary.goalDifference>0?`<p class="sheet-warning">O placar registra ${summary.scoreTotal} gols, mas a súmula detalha ${summary.recordedGoals}. ${summary.goalDifference===1?'Há 1 gol sem detalhe individual.':`Há ${summary.goalDifference} gols sem detalhe individual.`}</p>`:summary.goalDifference<0?`<p class="sheet-warning">Os eventos somam ${summary.recordedGoals} gols, enquanto o placar registra ${summary.scoreTotal}. A fonte apresenta essa divergência.</p>`:'';
  return heading+state+detailMetrics([[summary.recordedGoals,'Gols registrados'],[summary.totals.yellow,'Cartões amarelos'],[summary.totals.red,'Cartões vermelhos']])+mismatch+`<div class="match-stat-teams">${[m.team1,m.team2].filter(Boolean).map(groupHTML).join('')}${summary.unassigned?groupHTML(null):''}</div><p class="subtle">Somente gols e cartões deste jogo. Consulta da súmula: ${new Date(entry.fetchedAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})} · Brasília.</p>`;
}
async function updateCompletedDetails(){
  const completed=matches.filter(isFinished).map(m=>m.id);
  let cursor=0;
  await Promise.all(Array.from({length:Math.min(4,completed.length)},async()=>{
    while(cursor<completed.length)await loadMatchSheet(completed[cursor++]);
  }));
  if(db){render();if(activeMatchId)repaintMatch(activeMatchId);}
}
function repaintMatch(id){if(activeMatchId!==id||!$('#detail').open)return;const m=matches.find(m=>m.id===id);if(!m)return;const scroll=$('#detail').scrollTop;$('#detail-content').innerHTML=matchHTML(m);$('#detail').scrollTop=scroll}
async function loadMatchSheet(id,force=false){
  const cached=matchSheets.get(id);
  if(sheetRequests.has(id))return sheetRequests.get(id);
  if(!force&&cached&&!cached.error&&Date.now()-cached.fetchedAt<refreshPolicy(matches).interval)return;
  const task=(async()=>{
    try{
      const response=await fetch(`${BASE}/details/${encodeURIComponent(id)}.json`,{cache:'no-store',signal:AbortSignal.timeout(15000)});
      if(!response.ok)throw Error('HTTP '+response.status);
      const data=await response.json();
      if(data!==null&&(typeof data!=='object'||Array.isArray(data)))throw Error('Formato inválido');
      matchSheets.set(id,{data,fetchedAt:Date.now(),error:false});
    }catch{matchSheets.set(id,{data:cached?.data??null,fetchedAt:cached?.fetchedAt??Date.now(),error:true})}
    finally{sheetRequests.delete(id);recalculateScores();if(view==='ballon'||view==='players')render();if($('#detail').open){if(activePlayerId)openPlayer(activePlayerId,true);else if(activeTeamId)openTeam(activeTeamId,true);}repaintMatch(id)}
  })();
  sheetRequests.set(id,task);repaintMatch(id);return task;
}
let activePlayerId=null,activeTeamId=null;
function showDetail(html,preserve=false){if(preserve){const scroll=$('#detail').scrollTop;$('#detail-content').innerHTML=html;$('#detail').scrollTop=scroll;return}activeTeamId=null;activePlayerId=null;activeMatchId=null;activeFlyerId=null;if(flyerURL){URL.revokeObjectURL(flyerURL);flyerURL=null;}const d=$('#detail');$('#detail-content').innerHTML=html;d.setAttribute('aria-labelledby','detail-title');if(!d.open)d.showModal();d.scrollTop=0;$('#close-detail').focus()}
function openTeam(id,preserve=false){const t=standings().find(t=>t.id===id);if(!t)return;const roster=players.filter(p=>p.team===id).sort((a,b)=>(b.stats[0]||0)-(a.stats[0]||0)||a.name.localeCompare(b.name));const ms=matches.filter(m=>m.team1===id||m.team2===id);showDetail(`<div class="profile-heading">${crest(id)}<div><h2 id="detail-title">${esc(name(t.name))}</h2><p>${t.rank!=null?t.rank+1+'º lugar · ':''}${phaseLabel(phases[0])} · ${roster.length} jogadores</p></div></div>${detailMetrics([[t.pts,'Pontos'],[t.j,'Jogos'],[t.gp,'Gols pró']])}<div class="detail-info"><div><span>Campanha</span>${t.v} vitórias · ${t.e} empates · ${t.d} derrotas</div><div><span>Defesa e saldo</span>${t.gc} gols sofridos · saldo ${t.sg>0?'+':''}${t.sg}</div></div><h3 class="detail-section">Técnicos que comandaram a equipe</h3><div class="team-coach-history">${coachStatistics(db).filter(c=>c.games.some(g=>g.teamId===id)).map(c=>`<div>${coachButton(c)}<span class="subtle">${c.games.filter(g=>g.teamId===id).length} jogo(s) pela equipe</span></div>`).join('')||'<p class="subtle">Nenhum técnico informado para as partidas encerradas.</p>'}</div><h3 class="detail-section">Elenco completo</h3>${roster.length?playerTable(roster):'<p class="muted">Elenco não informado.</p>'}<h3 class="detail-section">Partidas da equipe</h3><div class="compact-list">${ms.length?ms.map(m=>`<p class="subtle">${fmtDate(m)} · ${phaseLabel(m.fs)} · ${roundLabel(m)}</p>${fixture(m)}`).join(''):'<p class="muted">Nenhuma partida cadastrada.</p>'}</div>`,preserve);activeTeamId=id}
function openPlayer(id,preserve=false){const p=players.find(p=>p.id===id);if(!p)return;const appearances=p.stats[2]||0,goals=p.stats[0]||0;const perPhase=[...new Set([...Object.keys(p.fs||{}),...Object.keys(p.appearances.byPhase)])].map(id=>[id,p.fs?.[id]||{}]);showDetail(`<div class="profile-heading">${avatar(p)}<div><h2 id="detail-title">${esc(name(p.name))}</h2><p>${esc(name(team(p.team)?.name))}</p>${goalkeeperBadge(p)}</div></div>${detailMetrics([[statValue(p,0),'Gols'],[statValue(p,2),'Jogos'],[statValue(p,14),'Cartões amarelos'],[statValue(p,16),'Cartões vermelhos']])}<div class="detail-info"><div><span>Média de gols por jogo</span>${appearances?(goals/appearances).toLocaleString('pt-BR',{maximumFractionDigits:2}):'Não disponível'}</div><div><span>Equipe</span>${teamButton(p.team)}</div></div>${p.SUSP?'<div class="source-info" style="background:#fff8e8;margin-top:20px;border-radius:8px">Há um registro de suspensão na fonte. Os dados fornecidos não permitem confirmar a duração ou se a suspensão ainda está em vigor.</div>':''}${playerAwardsHTML(p.id)}${playerScoreHTML(p.id)}${playerSelectionHistory(p.id)}<h3 class="detail-section">Desempenho por fase</h3>${perPhase.length?`<div class="table-wrap"><table><thead><tr><th>Fase</th><th>Gols</th><th>Jogos</th><th>C.AM</th><th>C.VM</th></tr></thead><tbody>${perPhase.map(([id,v])=>{const s=parseStats(v.dt);return `<tr><td>${phases.includes(id)?phaseLabel(id):'Fase não identificada'}</td><td>${s[0]||0}</td><td>${p.appearances.byPhase[id]||0}</td><td>${s[14]||0}</td><td>${s[16]||0}</td></tr>`}).join('')}</tbody></table></div>`:'<p class="muted">Estatísticas por fase ainda não informadas.</p>'}<p class="subtle">Jogos contam apenas presenças confirmadas nas súmulas de partidas encerradas. Reservas e não relacionados não contam. Súmulas ainda indisponíveis não entram na contagem. Os gols e cartões de cada jogo aparecem nos detalhes da partida.</p>`,preserve);activePlayerId=id}
function matchHTML(m){const h=standings(m.fs).find(t=>t.id===m.team1),a=standings(m.fs).find(t=>t.id===m.team2);return `<h2 id="detail-title" style="font-size:20px;margin-bottom:20px">${esc(name(team(m.team1)?.name))} × ${esc(name(team(m.team2)?.name))}</h2><div class="detail-match"><div style="text-align:center;margin-bottom:20px"><span class="badge ${isFinished(m)?'neutral':''}">${statusLabel(m)}</span></div><div class="fixture-body"><span class="fixture-team">${fixtureCrest(m,m.team1)}${esc(name(team(m.team1)?.name))}</span><span class="score">${scoreHTML(m)}</span><span class="fixture-team">${fixtureCrest(m,m.team2,true)}${esc(name(team(m.team2)?.name))}</span></div></div><div class="detail-info"><div><span>Data</span>${fmtDate(m,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div><div><span>Horário · Brasília</span>${fmtTime(m)}</div><div><span>Etapa</span>${phaseLabel(m.fs)} · ${roundLabel(m)}</div><div><span>Quadra</span>${esc(courtLabel(m.title)||'Não informada')}</div><div class="venue-detail"><span>Local</span><b>${VENUE.name}</b><br>${esc(VENUE.address)}</div><div><span>Resultado</span>${isFinished(m)?hasScore(m)?'Placar final registrado':'Placar não informado':'Aguardando encerramento'}</div></div>${liveCourtButton(m)}${matchCoachesHTML(m)}${recapHTML(m)}${previewHTML(m)}${flyerButton(m)}${matchStatistics(m)}${matchForecastDetail(m)}${m.fs===FIRST_PHASE&&h&&a?`<h3 class="detail-section">As equipes nesta fase</h3><div class="table-wrap"><table><thead><tr><th>Equipe</th><th>Pontos</th><th>Jogos</th><th>Gols</th></tr></thead><tbody>${[h,a].map(t=>`<tr><td>${teamButton(t.id)}</td><td>${t.pts}</td><td>${t.j}</td><td>${t.gp}</td></tr>`).join('')}</tbody></table></div>`:''}`}
function openMatch(id){const m=matches.find(m=>m.id===id);if(!m)return;showDetail(matchHTML(m));activeMatchId=id;loadMatchSheet(id)}
function switchView(){const next=location.hash.slice(1)||'overview';view=['overview','matches','standings','teams','players','odds','selection','motm','ballon','coaches'].includes(next)?next:'overview';filters={team:'',phase:view==='standings'?phases[0]||'':'',round:'',status:'',query:'',sort:'goals'};playerPage=1;if($('#detail').open)$('#detail').close();render()}
window.addEventListener('hashchange',switchView);
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-selection-round')){selectionId=e.target.value;render();return}const key=e.target.dataset.filter;if(!key)return;filters[key]=e.target.value;if(key==='phase')filters.round='';playerPage=1;render()});
document.addEventListener('input',e=>{if(e.target.matches('input[data-filter]')){filters[e.target.dataset.filter]=e.target.value;playerPage=1;render()}});
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.coach){openCoach(el.dataset.coach);return}if(el.dataset.motmPoster){openMotmPoster(el.dataset.motmPoster);return}if(el.dataset.flyer){openFlyer(el.dataset.flyer);return}if(el.dataset.sheetRefresh){loadMatchSheet(el.dataset.sheetRefresh,true);return}if(el.dataset.player)openPlayer(el.dataset.player);else if(el.dataset.team)openTeam(el.dataset.team);else if(el.dataset.match)openMatch(el.dataset.match);else if(el.hasAttribute('data-page')){playerPage+=el.dataset.page==='next'?1:-1;render()}else if(el.hasAttribute('data-reset')){filters={...filters,team:'',phase:'',round:'',status:'',query:''};render()}});
$('#close-detail').addEventListener('click',()=>$('#detail').close());
$('#detail').addEventListener('close',()=>{activeTeamId=null;activePlayerId=null;activeMatchId=null;activeFlyerId=null;if(flyerURL){URL.revokeObjectURL(flyerURL);flyerURL=null;}});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
function showNotice(message){$('#notice').hidden=!message;$('#notice').textContent=message}
async function refresh(){if(busy)return;updateVisitors();busy=true;lastRefreshAttempt=Date.now();clearTimeout(refreshTimer);$('#refresh').disabled=true;try{const payload=await Promise.all(['matchs','teams','player'].map(async endpoint=>{const r=await fetch(`${BASE}/${endpoint}.json`,{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('HTTP '+r.status);const j=await r.json();if(j!==null&&(typeof j!=='object'||Array.isArray(j)))throw Error('Formato inválido');return j||{}}));prepare({matchs:payload[0],teams:payload[1],player:payload[2],fetchedAt:new Date().toISOString()});$('#sync-state').textContent='Atualizado às '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});showNotice('');render();if(activeMatchId)loadMatchSheet(activeMatchId,true);await updateCompletedDetails()}catch(e){$('#sync-state').textContent='Sem conexão com a fonte';showNotice(db?'Não foi possível atualizar. Exibindo os dados consultados em '+new Date(db.fetchedAt).toLocaleString('pt-BR')+'. A próxima tentativa seguirá o intervalo indicado no topo.':'Não foi possível carregar os dados. Use o botão de atualizar para tentar novamente.')}finally{busy=false;$('#refresh').disabled=false;scheduleRefresh()}}
document.addEventListener('error',e=>{if(e.target instanceof HTMLImageElement){const s=document.createElement('span');s.className=e.target.classList.contains('avatar')?'avatar avatar-fallback':'badge-fallback';s.textContent='—';s.setAttribute('aria-hidden','true');e.target.replaceWith(s)}},true);
$('#refresh').addEventListener('click',refresh);
function scheduleRefresh(){
  clearTimeout(refreshTimer);
  const now=Date.now();
  $('#refresh-policy').textContent=refreshPolicy(matches,now).label;
  if(document.visibilityState!=='visible')return;
  const nextCheck=nextPolicyCheck(matches,lastRefreshAttempt,now);
  refreshTimer=setTimeout(()=>{
    if(document.visibilityState!=='visible')return;
    updateVisitors();
    if(Date.now()-lastRefreshAttempt>=refreshPolicy(matches).interval)refresh();
    else scheduleRefresh();
  },Math.max(1000,nextCheck-now));
}
async function init(){
  startVersionChecks();
  try{const r=await fetch('./data.json');if(!r.ok)throw Error();prepare(await r.json());$('#sync-state').textContent='Dados consultados em '+new Date(db.fetchedAt).toLocaleDateString('pt-BR');switchView()}catch{}
  await refresh();
  document.addEventListener('visibilitychange',()=>{
    if(document.visibilityState!=='visible'){clearTimeout(refreshTimer);return}
    updateVisitors();
    if(!busy&&Date.now()-lastRefreshAttempt>=refreshPolicy(matches).interval)refresh();
    else if(!busy)scheduleRefresh();
  });
}
init();
